CREATE DATABASE IF NOT EXISTS vst_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vst_db;
CREATE TABLE services(service_id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,slug VARCHAR(100) UNIQUE NOT NULL,description TEXT,icon VARCHAR(50),is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects(project_id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,category VARCHAR(100),description TEXT,tech_stack VARCHAR(500),status ENUM('DRAFT','PUBLISHED') DEFAULT 'DRAFT',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inquiries(inquiry_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL,phone VARCHAR(30),company VARCHAR(150),service_id INT,budget VARCHAR(50),message TEXT NOT NULL,status ENUM('NEW','CONTACTED','DISCUSSION','PROPOSAL','WON','LOST') DEFAULT 'NEW',priority ENUM('LOW','MEDIUM','HIGH') DEFAULT 'MEDIUM',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(service_id) REFERENCES services(service_id));
CREATE TABLE subscribers(subscriber_id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(150) UNIQUE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','STAFF') DEFAULT 'STAFF',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_chat_logs(chat_id INT AUTO_INCREMENT PRIMARY KEY,session_id VARCHAR(100),role ENUM('user','assistant') NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_inquiry_status ON inquiries(status); CREATE INDEX idx_inquiry_created ON inquiries(created_at); CREATE INDEX idx_project_status ON projects(status);
